-- Price currency contract:
-- * assets.currency is the native currency of the explicit assets.market_price fallback.
-- * asset_price_history.price_currency is the currency of close_price after applying
--   price_scale_factor once.
-- * asset_source_symbols.price_currency is the expected provider quote currency.
-- Valuation converts the selected historical/current price directly to its target;
-- it never normalizes a price through assets.currency first.
UPDATE investory.asset_price_history aph
SET quality_class = aph.quality_class || '_PERCENT_OF_PAR'
FROM investory.assets a
WHERE a.id = aph.asset_id
  AND a.asset_type = 'BOND'
  AND aph.source IN ('TWELVE_DATA', 'YAHOO_FINANCE')
  AND aph.quality_class NOT LIKE '%PERCENT_OF_PAR%';

-- assets.market_price is the legacy monetary per-unit cache used by position synchronization.
UPDATE investory.assets
SET market_price = market_price * 0.01,
    market_price_usd = market_price_usd * 0.01
WHERE asset_type = 'BOND'
  AND price_source IN ('TwelveData', 'YahooFinance')
  AND market_price IS NOT NULL
  AND market_price > 10;